-- VOTILT, PostgreSQL 18 native. Canonical fresh-install schema. No Docker.
CREATE SCHEMA IF NOT EXISTS private;
CREATE SCHEMA IF NOT EXISTS api;
REVOKE ALL ON SCHEMA private,api FROM PUBLIC;

CREATE TABLE IF NOT EXISTS public.profiles (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), handle text NOT NULL UNIQUE CHECK(handle ~ '^[a-z0-9_]{3,24}$'),
 display_name text NOT NULL CHECK(length(display_name) BETWEEN 1 AND 60), bio text NOT NULL DEFAULT '' CHECK(length(bio)<=160),
 visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','friends','private')),
 suspended boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS private.credentials (
 user_id uuid PRIMARY KEY REFERENCES public.profiles ON DELETE CASCADE,
 email text UNIQUE NOT NULL, password_hash text NOT NULL
);
CREATE TABLE IF NOT EXISTS private.sessions (
 token_hash text PRIMARY KEY, user_id uuid NOT NULL REFERENCES public.profiles ON DELETE CASCADE,
 expires_at timestamptz NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.profile_settings (
 user_id uuid PRIMARY KEY REFERENCES public.profiles ON DELETE CASCADE,
 show_champions text NOT NULL DEFAULT 'owner' CHECK(show_champions IN ('owner','friends','public')),
 allow_comparison boolean NOT NULL DEFAULT false, haptics boolean NOT NULL DEFAULT true,
 reduce_motion boolean NOT NULL DEFAULT false, onboarding_complete boolean NOT NULL DEFAULT false
);
CREATE TABLE IF NOT EXISTS public.user_roles (
 user_id uuid PRIMARY KEY REFERENCES public.profiles ON DELETE CASCADE,
 role text NOT NULL DEFAULT 'user' CHECK(role IN ('user','moderator','admin'))
);
CREATE TABLE IF NOT EXISTS public.categories (
 id uuid PRIMARY KEY, parent_id uuid REFERENCES public.categories ON DELETE RESTRICT,
 depth integer NOT NULL CHECK(depth BETWEEN 1 AND 32), slug text NOT NULL, title text NOT NULL,
 description text NOT NULL DEFAULT '', icon text NOT NULL DEFAULT 'sparkles', sort_order integer NOT NULL DEFAULT 0,
 status text NOT NULL DEFAULT 'published' CHECK(status IN ('published','draft','archived')),
 reference_kind text NOT NULL DEFAULT 'name' CHECK(reference_kind IN ('name','person','website','place','tool')),
 reference_label text NOT NULL DEFAULT 'Nome del soggetto', requires_url boolean NOT NULL DEFAULT false,
 CHECK((parent_id IS NULL) = (depth=1)), UNIQUE NULLS NOT DISTINCT(parent_id,slug)
);
CREATE TABLE IF NOT EXISTS public.user_category_interests (
 user_id uuid REFERENCES public.profiles ON DELETE CASCADE, category_id uuid REFERENCES public.categories ON DELETE CASCADE,
 PRIMARY KEY(user_id,category_id)
);
CREATE TABLE IF NOT EXISTS public.content_items (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), author_id uuid NOT NULL REFERENCES public.profiles ON DELETE CASCADE,
 kind text NOT NULL CHECK(kind IN ('photo','illustration','ai_art','ai_tool')),
 title text NOT NULL CHECK(length(title) BETWEEN 1 AND 80), caption text NOT NULL DEFAULT '' CHECK(length(caption)<=400),
 visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','friends','private')),
 media_path text NOT NULL UNIQUE, provenance text NOT NULL DEFAULT 'original_illustration'
   CHECK(provenance IN ('original_illustration','ai_generated','verified_real','unknown','demo_placeholder')),
 moderation_status text NOT NULL DEFAULT 'draft' CHECK(moderation_status IN ('draft','pending_review','approved','rejected','hidden','removed')),
 review_reason text, created_at timestamptz NOT NULL DEFAULT now(), approved_at timestamptz,
 rights_attested boolean NOT NULL DEFAULT false, adult_consent boolean NOT NULL DEFAULT false,
 byte_size integer, mime_type text, width integer, height integer
);
CREATE TABLE IF NOT EXISTS public.content_categories (
 content_id uuid REFERENCES public.content_items ON DELETE CASCADE, category_id uuid REFERENCES public.categories ON DELETE RESTRICT,
 status text NOT NULL DEFAULT 'approved' CHECK(status IN ('pending','approved','rejected')),
 PRIMARY KEY(content_id,category_id)
);
CREATE TABLE IF NOT EXISTS public.vote_slots (
 user_id uuid REFERENCES public.profiles ON DELETE CASCADE, category_id uuid REFERENCES public.categories ON DELETE RESTRICT,
 champion_content_id uuid REFERENCES public.content_items ON DELETE RESTRICT,
 version integer NOT NULL DEFAULT 0 CHECK(version>=0), updated_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(user_id,category_id), FOREIGN KEY(champion_content_id,category_id) REFERENCES public.content_categories(content_id,category_id)
);
CREATE TABLE IF NOT EXISTS public.content_metadata (
 content_id uuid NOT NULL, category_id uuid NOT NULL, subject_name text NOT NULL CHECK(length(trim(subject_name)) BETWEEN 1 AND 120),
 reference_url text CHECK(reference_url IS NULL OR reference_url ~ '^https?://[^[:space:]@]+$'),
 PRIMARY KEY(content_id,category_id), FOREIGN KEY(content_id,category_id) REFERENCES public.content_categories ON DELETE CASCADE
);
CREATE INDEX IF NOT EXISTS metadata_subject_idx ON public.content_metadata(lower(subject_name));
CREATE TABLE IF NOT EXISTS public.tilt_duels (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid NOT NULL REFERENCES public.profiles ON DELETE CASCADE,
 category_id uuid NOT NULL REFERENCES public.categories, incumbent_id uuid NOT NULL REFERENCES public.content_items ON DELETE CASCADE,
 challenger_id uuid NOT NULL REFERENCES public.content_items ON DELETE CASCADE, expected_slot_version integer NOT NULL,
 status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','resolved','expired','stale','superseded','cancelled')),
 winner_side text CHECK(winner_side IN ('INCUMBENT','CHALLENGER')), created_at timestamptz NOT NULL DEFAULT now(),
 expires_at timestamptz NOT NULL DEFAULT now()+interval '15 minutes', resolved_at timestamptz,
 CHECK(incumbent_id<>challenger_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS tilt_one_pending ON public.tilt_duels(user_id,category_id) WHERE status='pending';
CREATE TABLE IF NOT EXISTS public.vote_events (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), user_id uuid REFERENCES public.profiles ON DELETE SET NULL,
 category_id uuid NOT NULL REFERENCES public.categories, kind text NOT NULL CHECK(kind IN ('initial','transfer','confirmed','invalidated')),
 old_content_id uuid, new_content_id uuid, duel_id uuid, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.operation_receipts (
 user_id uuid REFERENCES public.profiles ON DELETE CASCADE, operation_id uuid NOT NULL, action text NOT NULL,
 fingerprint text NOT NULL, result_json jsonb NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(user_id,operation_id,action)
);
CREATE TABLE IF NOT EXISTS public.duel_ratings (
 category_id uuid REFERENCES public.categories, content_id uuid REFERENCES public.content_items ON DELETE CASCADE,
 rating numeric NOT NULL DEFAULT 1500, matches integer NOT NULL DEFAULT 0 CHECK(matches>=0),
 wins integer NOT NULL DEFAULT 0 CHECK(wins>=0), losses integer NOT NULL DEFAULT 0 CHECK(losses>=0),
 PRIMARY KEY(category_id,content_id), CHECK(matches=wins+losses)
);
CREATE TABLE IF NOT EXISTS public.rating_events (
 duel_id uuid PRIMARY KEY REFERENCES public.tilt_duels ON DELETE CASCADE, user_id uuid REFERENCES public.profiles ON DELETE SET NULL,
 category_id uuid REFERENCES public.categories, winner_id uuid, loser_id uuid, rated boolean NOT NULL,
 formula_version text NOT NULL DEFAULT 'elo-1500-k32-v1', old_winner numeric, new_winner numeric, old_loser numeric, new_loser numeric,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.user_blocks (
 blocker_id uuid REFERENCES public.profiles ON DELETE CASCADE, blocked_id uuid REFERENCES public.profiles ON DELETE CASCADE,
 PRIMARY KEY(blocker_id,blocked_id), CHECK(blocker_id<>blocked_id)
);
CREATE TABLE IF NOT EXISTS public.follows (
 follower_id uuid REFERENCES public.profiles ON DELETE CASCADE, followed_id uuid REFERENCES public.profiles ON DELETE CASCADE,
 PRIMARY KEY(follower_id,followed_id), CHECK(follower_id<>followed_id)
);
CREATE TABLE IF NOT EXISTS public.friend_requests (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), requester_id uuid REFERENCES public.profiles ON DELETE CASCADE,
 recipient_id uuid REFERENCES public.profiles ON DELETE CASCADE, status text NOT NULL DEFAULT 'pending'
 CHECK(status IN ('pending','accepted','rejected','cancelled')), created_at timestamptz NOT NULL DEFAULT now(),
 CHECK(requester_id<>recipient_id)
);
CREATE UNIQUE INDEX IF NOT EXISTS friend_one_pending ON public.friend_requests(least(requester_id,recipient_id),greatest(requester_id,recipient_id)) WHERE status='pending';
CREATE TABLE IF NOT EXISTS public.friendships (
 user_low_id uuid REFERENCES public.profiles ON DELETE CASCADE, user_high_id uuid REFERENCES public.profiles ON DELETE CASCADE,
 PRIMARY KEY(user_low_id,user_high_id), CHECK(user_low_id<user_high_id)
);
CREATE TABLE IF NOT EXISTS public.battle_shares (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), creator_id uuid REFERENCES public.profiles ON DELETE CASCADE,
 recipient_id uuid NOT NULL REFERENCES public.profiles ON DELETE CASCADE, category_id uuid REFERENCES public.categories,
 expires_at timestamptz NOT NULL DEFAULT now()+interval '24 hours', revoked boolean NOT NULL DEFAULT false
);
CREATE TABLE IF NOT EXISTS public.notifications (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), recipient_id uuid REFERENCES public.profiles ON DELETE CASCADE,
 type text NOT NULL, title text NOT NULL, entity_id uuid, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.reports (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), reporter_id uuid REFERENCES public.profiles ON DELETE SET NULL,
 content_id uuid REFERENCES public.content_items ON DELETE CASCADE, reason text NOT NULL CHECK(length(reason) BETWEEN 3 AND 500),
 status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','reviewed','dismissed')), created_at timestamptz NOT NULL DEFAULT now(),
 UNIQUE(reporter_id,content_id)
);
CREATE TABLE IF NOT EXISTS public.moderation_actions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), moderator_id uuid REFERENCES public.profiles ON DELETE SET NULL,
 target_id uuid, action text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.category_suggestions (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), proposer_id uuid REFERENCES public.profiles ON DELETE SET NULL,
 parent_id uuid NOT NULL REFERENCES public.categories, title text NOT NULL CHECK(length(title) BETWEEN 3 AND 60),
 description text NOT NULL CHECK(length(description) BETWEEN 20 AND 250), examples jsonb NOT NULL CHECK(jsonb_array_length(examples) BETWEEN 0 AND 10),
 status text NOT NULL DEFAULT 'pending' CHECK(status IN ('pending','approved','rejected')), review_reason text, created_at timestamptz NOT NULL DEFAULT now()
);
ALTER TABLE public.category_suggestions ADD COLUMN IF NOT EXISTS reference_kind text NOT NULL DEFAULT 'name' CHECK(reference_kind IN ('name','person','website','place','tool'));
ALTER TABLE public.category_suggestions DROP CONSTRAINT IF EXISTS category_suggestions_description_check;
ALTER TABLE public.category_suggestions ADD CONSTRAINT category_suggestions_description_check CHECK(length(description) BETWEEN 20 AND 250);
ALTER TABLE public.category_suggestions DROP CONSTRAINT IF EXISTS category_suggestions_examples_check;
ALTER TABLE public.category_suggestions ADD CONSTRAINT category_suggestions_examples_check CHECK(jsonb_array_length(examples) BETWEEN 0 AND 10);
CREATE TABLE IF NOT EXISTS public.daily_challenges (
 date_utc date PRIMARY KEY, category_id uuid REFERENCES public.categories
);
CREATE TABLE IF NOT EXISTS public.ranking_snapshots (
 date_utc date, category_id uuid REFERENCES public.categories, content_id uuid REFERENCES public.content_items ON DELETE CASCADE,
 support integer NOT NULL CHECK(support>=0), PRIMARY KEY(date_utc,category_id,content_id)
);
CREATE TABLE IF NOT EXISTS public.content_impressions (
 user_id uuid REFERENCES public.profiles ON DELETE CASCADE, content_id uuid REFERENCES public.content_items ON DELETE CASCADE,
 category_id uuid REFERENCES public.categories, session_id uuid NOT NULL, seen_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(user_id,content_id,category_id,session_id)
);
CREATE TABLE IF NOT EXISTS private.quiz_items (
 id uuid PRIMARY KEY DEFAULT gen_random_uuid(), media_path text NOT NULL, ground_truth text CHECK(ground_truth IN ('REAL','AI')),
 evidence_note text NOT NULL, enabled boolean NOT NULL DEFAULT false, test_only boolean NOT NULL DEFAULT true
);
CREATE TABLE IF NOT EXISTS public.real_ai_answers (
 user_id uuid REFERENCES public.profiles ON DELETE CASCADE, quiz_item_id uuid REFERENCES private.quiz_items ON DELETE CASCADE,
 answer text CHECK(answer IN ('REAL','AI')), is_correct boolean NOT NULL, created_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(user_id,quiz_item_id)
);
CREATE INDEX IF NOT EXISTS slots_champion_idx ON public.vote_slots(category_id,champion_content_id);
CREATE INDEX IF NOT EXISTS content_status_idx ON public.content_items(moderation_status,created_at DESC,id);
CREATE INDEX IF NOT EXISTS duel_user_idx ON public.tilt_duels(user_id,created_at DESC);
CREATE INDEX IF NOT EXISTS notification_user_idx ON public.notifications(recipient_id,created_at DESC);
CREATE INDEX IF NOT EXISTS rating_cooldown_idx ON public.rating_events(user_id,category_id,created_at DESC) WHERE rated;
ALTER TABLE public.content_items ADD COLUMN IF NOT EXISTS visibility text NOT NULL DEFAULT 'public' CHECK(visibility IN ('public','friends','private'));
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS reference_kind text NOT NULL DEFAULT 'name' CHECK(reference_kind IN ('name','person','website','place','tool'));
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS reference_label text NOT NULL DEFAULT 'Nome del soggetto';
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS requires_url boolean NOT NULL DEFAULT false;
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS allowed_kinds text[] NOT NULL DEFAULT ARRAY['photo','illustration','ai_art']::text[] CHECK(cardinality(allowed_kinds)>0 AND allowed_kinds <@ ARRAY['photo','illustration','ai_art','ai_tool']::text[]);
ALTER TABLE public.content_items DROP CONSTRAINT IF EXISTS content_items_title_check;
ALTER TABLE public.content_items ADD CONSTRAINT content_items_title_check CHECK(length(title) BETWEEN 1 AND 80);

ALTER TABLE public.categories DROP CONSTRAINT IF EXISTS categories_depth_check;
ALTER TABLE public.categories ADD CONSTRAINT categories_depth_check CHECK(depth BETWEEN 1 AND 32);
ALTER TABLE public.categories ADD COLUMN IF NOT EXISTS aliases text[] NOT NULL DEFAULT ARRAY[]::text[];
ALTER TABLE public.vote_slots ADD COLUMN IF NOT EXISTS origin_content_id uuid REFERENCES public.content_items ON DELETE SET NULL;
ALTER TABLE public.content_items ADD COLUMN IF NOT EXISTS tags text[] NOT NULL DEFAULT ARRAY[]::text[] CHECK(cardinality(tags)<=20);
CREATE TABLE IF NOT EXISTS public.category_follows (
 user_id uuid REFERENCES public.profiles ON DELETE CASCADE, category_id uuid REFERENCES public.categories ON DELETE CASCADE,
 PRIMARY KEY(user_id,category_id)
);
CREATE TABLE IF NOT EXISTS public.creator_duel_ratings (
 category_id uuid REFERENCES public.categories, author_id uuid REFERENCES public.profiles ON DELETE CASCADE,
 rating numeric NOT NULL DEFAULT 1500, matches integer NOT NULL DEFAULT 0 CHECK(matches>=0),
 wins integer NOT NULL DEFAULT 0 CHECK(wins>=0), losses integer NOT NULL DEFAULT 0 CHECK(losses>=0),
 PRIMARY KEY(category_id,author_id), CHECK(matches=wins+losses)
);
CREATE TABLE IF NOT EXISTS public.creator_rating_events (
 duel_id uuid PRIMARY KEY REFERENCES public.tilt_duels ON DELETE CASCADE, user_id uuid REFERENCES public.profiles ON DELETE SET NULL,
 category_id uuid REFERENCES public.categories, winner_id uuid, loser_id uuid, rated boolean NOT NULL,
 formula_version text NOT NULL DEFAULT 'creator-elo-1500-k32-v1', old_winner numeric, new_winner numeric, old_loser numeric, new_loser numeric,
 created_at timestamptz NOT NULL DEFAULT now()
);
CREATE TABLE IF NOT EXISTS public.creator_ranking_snapshots (
 date_utc date, category_id uuid REFERENCES public.categories, author_id uuid REFERENCES public.profiles ON DELETE CASCADE,
 support integer NOT NULL CHECK(support>=0), PRIMARY KEY(date_utc,category_id,author_id)
);
CREATE TABLE IF NOT EXISTS private.model_migrations (name text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE IF NOT EXISTS private.legacy_membership_archive (
 content_id uuid, category_id uuid, membership jsonb NOT NULL, archived_at timestamptz NOT NULL DEFAULT now(),
 PRIMARY KEY(content_id,category_id)
);

CREATE OR REPLACE FUNCTION api.uid() RETURNS uuid LANGUAGE sql STABLE AS $$ SELECT nullif(current_setting('app.user_id',true),'')::uuid $$;
CREATE OR REPLACE FUNCTION api.is_mod() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=api.uid() AND role IN ('admin','moderator')) $$;
CREATE OR REPLACE FUNCTION api.blocked(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.user_blocks WHERE (blocker_id=a AND blocked_id=b) OR (blocker_id=b AND blocked_id=a)) $$;
CREATE OR REPLACE FUNCTION api.friends(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.friendships WHERE user_low_id=least(a,b) AND user_high_id=greatest(a,b)) $$;
CREATE OR REPLACE FUNCTION api.can_read(c public.content_items) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT NOT api.blocked(api.uid(),c.author_id) AND EXISTS(SELECT 1 FROM public.profiles WHERE id=c.author_id AND NOT suspended)
 AND ((c.moderation_status='approved' AND (c.visibility='public' OR (c.visibility='friends' AND api.friends(api.uid(),c.author_id)))) OR (api.uid()=c.author_id AND c.moderation_status<>'removed') OR api.is_mod()) $$;
CREATE OR REPLACE FUNCTION api.content_json(cid uuid, cat uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT jsonb_build_object('id',c.id,'title',coalesce((SELECT subject_name FROM public.content_metadata WHERE content_id=c.id AND category_id=cat),c.title),'caption',c.caption,'kind',c.kind,'provenance',c.provenance,
 'status',c.moderation_status,'visibility',c.visibility,'reviewReason',c.review_reason,'authorId',p.id,'handle',p.handle,'displayName',p.display_name,
 'mediaUrl','/media/'||c.id,'categoryId',cat,'categoryTitle',(SELECT title FROM public.categories WHERE id=cat),
 'reference',(SELECT jsonb_build_object('name',m.subject_name,'url',m.reference_url,'label',rules.reference_label,'kind',rules.reference_kind)
   FROM public.content_metadata m JOIN public.categories rules ON rules.id=m.category_id WHERE m.content_id=c.id AND m.category_id=cat),
 'references',coalesce((SELECT jsonb_agg(jsonb_build_object('categoryId',m.category_id,'categoryTitle',rules.title,'name',m.subject_name,'url',m.reference_url,'label',rules.reference_label,'kind',rules.reference_kind,'status',cc.status))
   FROM public.content_metadata m JOIN public.categories rules ON rules.id=m.category_id JOIN public.content_categories cc ON cc.content_id=m.content_id AND cc.category_id=m.category_id
   WHERE m.content_id=c.id AND rules.status='published' AND (cc.status='approved' OR c.author_id=api.uid() OR api.is_mod())),'[]'))
 FROM public.content_items c JOIN public.profiles p ON p.id=c.author_id WHERE c.id=cid AND api.can_read(c)
 AND (cat IS NULL OR EXISTS(SELECT 1 FROM public.content_categories cc JOIN public.categories rules ON rules.id=cc.category_id
 WHERE cc.content_id=c.id AND cc.category_id=cat AND rules.status='published' AND (cc.status='approved' OR c.author_id=api.uid() OR api.is_mod()))) $$;

CREATE OR REPLACE FUNCTION api.validate_candidate(cid uuid,cat uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=cat AND status='published') THEN RAISE EXCEPTION 'CATEGORY_NOT_LEAF'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.content_items c JOIN public.content_categories cc ON cc.content_id=c.id
   JOIN public.profiles p ON p.id=c.author_id WHERE c.id=cid AND cc.category_id=cat AND cc.status='approved'
   AND c.moderation_status='approved' AND NOT p.suspended) THEN RAISE EXCEPTION 'CONTENT_UNAVAILABLE'; END IF;
 IF EXISTS(SELECT 1 FROM public.content_items WHERE id=cid AND api.blocked(api.uid(),author_id)) THEN RAISE EXCEPTION 'BLOCKED_CONTENT'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.content_items c WHERE c.id=cid AND api.can_read(c)) THEN RAISE EXCEPTION 'CONTENT_UNAVAILABLE'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.content_metadata m JOIN public.categories c ON c.id=m.category_id WHERE m.content_id=cid AND m.category_id=cat AND length(trim(m.subject_name))>0 AND (NOT c.requires_url OR nullif(m.reference_url,'') IS NOT NULL)) THEN RAISE EXCEPTION 'METADATA_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.categories rules JOIN public.content_items c ON c.id=cid WHERE rules.id=cat AND c.kind=ANY(rules.allowed_kinds)) THEN RAISE EXCEPTION 'INVALID_CONTENT_KIND'; END IF;
END $$;

CREATE OR REPLACE FUNCTION api.vote(p jsonb, action_name text) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE
 u uuid:=api.uid(); op uuid:=(p->>'clientOperationId')::uuid; cat uuid; cid uuid; did uuid;
 slot public.vote_slots; duel public.tilt_duels; receipt public.operation_receipts; result jsonb; winner uuid; loser uuid;
 win_rating numeric; lose_rating numeric; delta numeric; is_rated boolean; changed boolean; win_author uuid; lose_author uuid;
BEGIN
 IF u IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT suspended) THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 IF op IS NULL THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
 -- debt: serialisation globale pour demo locale; raffiner par categorie apres mesure d'un goulot de contention.
 -- All vote/moderation/block/deletion mutations acquire this lock before row locks.
 PERFORM pg_advisory_xact_lock(8815001);
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT suspended) THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 SELECT * INTO receipt FROM public.operation_receipts WHERE user_id=u AND operation_id=op AND action=action_name||':creator-v1';
 IF FOUND THEN
   IF receipt.fingerprint<>md5(p::text) THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSE'; END IF;
   RETURN receipt.result_json;
 END IF;
 IF action_name='vote_intent' THEN
   cat:=(p->>'categoryId')::uuid; cid:=(p->>'contentId')::uuid;
   PERFORM api.validate_candidate(cid,cat);
   INSERT INTO public.vote_slots(user_id,category_id) VALUES(u,cat) ON CONFLICT DO NOTHING;
   SELECT * INTO slot FROM public.vote_slots WHERE user_id=u AND category_id=cat FOR UPDATE;
   IF slot.champion_content_id IS NULL THEN
     UPDATE public.vote_slots SET champion_content_id=cid,origin_content_id=cid,version=version+1,updated_at=now() WHERE user_id=u AND category_id=cat RETURNING * INTO slot;
     INSERT INTO public.vote_events(user_id,category_id,kind,new_content_id) VALUES(u,cat,'initial',cid);
     result:=jsonb_build_object('kind','INITIAL_VOTE','championId',cid,'slotVersion',slot.version);
   ELSIF (SELECT author_id FROM public.content_items WHERE id=slot.champion_content_id)=(SELECT author_id FROM public.content_items WHERE id=cid) THEN
     result:=jsonb_build_object('kind','ALREADY_CHAMPION','championId',cid,'slotVersion',slot.version);
   ELSE
     PERFORM api.validate_candidate(slot.champion_content_id,cat);
     UPDATE public.tilt_duels SET status='superseded' WHERE user_id=u AND category_id=cat AND status='pending';
     INSERT INTO public.tilt_duels(user_id,category_id,incumbent_id,challenger_id,expected_slot_version)
       VALUES(u,cat,slot.champion_content_id,cid,slot.version) RETURNING * INTO duel;
     result:=jsonb_build_object('kind','TILT_REQUIRED','duelId',duel.id,'categoryId',cat,'incumbentId',duel.incumbent_id,
       'challengerId',cid,'expectedSlotVersion',slot.version,'expiresAt',duel.expires_at);
   END IF;
 ELSIF action_name IN ('resolve_tilt','cancel_tilt') THEN
   did:=(p->>'duelId')::uuid;
   SELECT * INTO duel FROM public.tilt_duels WHERE id=did AND user_id=u;
   IF NOT FOUND THEN RAISE EXCEPTION 'DUEL_NOT_FOUND'; END IF;
   cat:=duel.category_id;
   SELECT * INTO slot FROM public.vote_slots WHERE user_id=u AND category_id=cat FOR UPDATE;
   SELECT * INTO duel FROM public.tilt_duels WHERE id=did FOR UPDATE;
   IF duel.status='superseded' THEN RAISE EXCEPTION 'DUEL_SUPERSEDED'; END IF;
   IF duel.status<>'pending' THEN RAISE EXCEPTION 'DUEL_STALE'; END IF;
   IF duel.expires_at<=now() THEN RAISE EXCEPTION 'DUEL_EXPIRED'; END IF;
   IF slot.version<>duel.expected_slot_version OR slot.champion_content_id IS DISTINCT FROM duel.incumbent_id THEN RAISE EXCEPTION 'DUEL_STALE'; END IF;
   IF action_name='cancel_tilt' THEN
     UPDATE public.tilt_duels SET status='cancelled' WHERE id=did;
     result:=jsonb_build_object('kind','TILT_CANCELLED','duelId',did);
   ELSE
     IF p->>'winnerSide' NOT IN ('INCUMBENT','CHALLENGER') OR p->>'winnerSide' IS NULL THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
     PERFORM api.validate_candidate(duel.incumbent_id,cat); PERFORM api.validate_candidate(duel.challenger_id,cat);
     changed:=(p->>'winnerSide'='CHALLENGER');
     winner:=CASE WHEN changed THEN duel.challenger_id ELSE duel.incumbent_id END;
     loser:=CASE WHEN changed THEN duel.incumbent_id ELSE duel.challenger_id END;
     IF changed THEN
       UPDATE public.vote_slots SET champion_content_id=winner,origin_content_id=winner,version=version+1,updated_at=now() WHERE user_id=u AND category_id=cat RETURNING * INTO slot;
     END IF;
     INSERT INTO public.vote_events(user_id,category_id,kind,old_content_id,new_content_id,duel_id)
       VALUES(u,cat,CASE WHEN changed THEN 'transfer' ELSE 'confirmed' END,duel.incumbent_id,winner,did);
     SELECT author_id INTO win_author FROM public.content_items WHERE id=winner;
     SELECT author_id INTO lose_author FROM public.content_items WHERE id=loser;
     IF win_author=lose_author THEN RAISE EXCEPTION 'DUEL_STALE'; END IF;
     INSERT INTO public.creator_duel_ratings(category_id,author_id) VALUES(cat,win_author),(cat,lose_author) ON CONFLICT DO NOTHING;
     PERFORM author_id FROM public.creator_duel_ratings WHERE category_id=cat AND author_id IN(win_author,lose_author) ORDER BY author_id FOR UPDATE;
     SELECT rating INTO win_rating FROM public.creator_duel_ratings WHERE category_id=cat AND author_id=win_author;
     SELECT rating INTO lose_rating FROM public.creator_duel_ratings WHERE category_id=cat AND author_id=lose_author;
     is_rated:=NOT EXISTS(SELECT 1 FROM public.creator_rating_events WHERE user_id=u AND category_id=cat AND rated AND created_at>now()-interval '24 hours'
       AND least(winner_id,loser_id)=least(win_author,lose_author) AND greatest(winner_id,loser_id)=greatest(win_author,lose_author));
     delta:=CASE WHEN is_rated THEN 32*(1-1/(1+power(10::numeric,(lose_rating-win_rating)/400))) ELSE 0 END;
     IF is_rated THEN
       UPDATE public.creator_duel_ratings SET rating=rating+delta,matches=matches+1,wins=wins+1 WHERE category_id=cat AND author_id=win_author;
       UPDATE public.creator_duel_ratings SET rating=rating-delta,matches=matches+1,losses=losses+1 WHERE category_id=cat AND author_id=lose_author;
     END IF;
     INSERT INTO public.creator_rating_events(duel_id,user_id,category_id,winner_id,loser_id,rated,old_winner,new_winner,old_loser,new_loser)
       VALUES(did,u,cat,win_author,lose_author,is_rated,win_rating,win_rating+delta,lose_rating,lose_rating-delta);
     UPDATE public.tilt_duels SET status='resolved',winner_side=p->>'winnerSide',resolved_at=now() WHERE id=did;
     UPDATE public.tilt_duels SET status='superseded' WHERE user_id=u AND category_id=cat AND status='pending';
     result:=jsonb_build_object('kind','TILT_RESOLVED','duelId',did,'categoryId',cat,'winnerContentId',winner,
       'championContentId',winner,'didChampionChange',changed,'slotVersion',slot.version,'rated',is_rated);
   END IF;
 ELSE RAISE EXCEPTION 'INVALID_ACTION'; END IF;
 result:=result||jsonb_build_object('receiptId',op);
 INSERT INTO public.operation_receipts VALUES(u,op,action_name||':creator-v1',md5(p::text),result,now());
 RETURN result;
END $$;

-- The API role can read only through RLS or constrained SECURITY DEFINER functions.
DO $policies$
DECLARE t text;
BEGIN
 FOR t IN SELECT tablename FROM pg_tables WHERE schemaname='public' LOOP
   EXECUTE format('ALTER TABLE public.%I ENABLE ROW LEVEL SECURITY',t);
   EXECUTE format('REVOKE ALL ON public.%I FROM PUBLIC',t);
 END LOOP;
END $policies$;
DROP POLICY IF EXISTS visible_profiles ON public.profiles;
CREATE POLICY visible_profiles ON public.profiles FOR SELECT USING(NOT suspended AND NOT api.blocked(api.uid(),id) AND (visibility='public' OR id=api.uid() OR (visibility='friends' AND api.friends(id,api.uid()))));
DROP POLICY IF EXISTS visible_categories ON public.categories;
CREATE POLICY visible_categories ON public.categories FOR SELECT USING(status='published');
DROP POLICY IF EXISTS visible_content ON public.content_items;
CREATE POLICY visible_content ON public.content_items FOR SELECT USING(api.can_read(content_items));
DROP POLICY IF EXISTS own_settings ON public.profile_settings;
CREATE POLICY own_settings ON public.profile_settings FOR SELECT USING(user_id=api.uid());
DROP POLICY IF EXISTS own_roles ON public.user_roles;
CREATE POLICY own_roles ON public.user_roles FOR SELECT USING(user_id=api.uid());
DROP POLICY IF EXISTS own_slots ON public.vote_slots;
CREATE POLICY own_slots ON public.vote_slots FOR SELECT USING(user_id=api.uid());
DROP POLICY IF EXISTS own_duels ON public.tilt_duels;
CREATE POLICY own_duels ON public.tilt_duels FOR SELECT USING(user_id=api.uid());
DROP POLICY IF EXISTS own_notifications ON public.notifications;
CREATE POLICY own_notifications ON public.notifications FOR SELECT USING(recipient_id=api.uid());
DROP POLICY IF EXISTS visible_metadata ON public.content_metadata;
CREATE POLICY visible_metadata ON public.content_metadata FOR SELECT USING(EXISTS(SELECT 1 FROM public.content_items c JOIN public.content_categories cc ON cc.content_id=c.id JOIN public.categories rules ON rules.id=cc.category_id WHERE c.id=content_metadata.content_id AND cc.category_id=content_metadata.category_id AND rules.status='published' AND api.can_read(c) AND (cc.status='approved' OR c.author_id=api.uid() OR api.is_mod())));
DROP POLICY IF EXISTS visible_memberships ON public.content_categories;
CREATE POLICY visible_memberships ON public.content_categories FOR SELECT USING(EXISTS(SELECT 1 FROM public.content_items c WHERE c.id=content_categories.content_id AND api.can_read(c) AND (content_categories.status='approved' OR c.author_id=api.uid() OR api.is_mod())));
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA api FROM PUBLIC;

CREATE OR REPLACE FUNCTION api.register_user(p_id uuid,p_email text,p_hash text,p_handle text,p_name text) RETURNS void
LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 IF p_handle IN ('admin','moderator','votilt','support','administrator') THEN RAISE EXCEPTION 'HANDLE_RESERVED'; END IF;
 INSERT INTO public.profiles(id,handle,display_name) VALUES(p_id,p_handle,p_name);
 INSERT INTO private.credentials VALUES(p_id,lower(p_email),p_hash);
 INSERT INTO public.profile_settings(user_id) VALUES(p_id);
 INSERT INTO public.user_roles(user_id) VALUES(p_id);
END $$;

CREATE OR REPLACE FUNCTION api.can_compare(a uuid,b uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT a=b OR (NOT api.blocked(a,b) AND api.friends(a,b)
 AND EXISTS(SELECT 1 FROM public.profile_settings WHERE user_id=a AND allow_comparison AND show_champions IN ('friends','public'))
 AND EXISTS(SELECT 1 FROM public.profile_settings WHERE user_id=b AND allow_comparison AND show_champions IN ('friends','public'))) $$;

CREATE OR REPLACE FUNCTION api.dispatch(action_name text,p jsonb DEFAULT '{}'::jsonb) RETURNS jsonb LANGUAGE plpgsql
SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE
 u uuid:=api.uid(); target uuid; cid uuid; cat uuid; req public.friend_requests; item public.content_items;
 suggestion public.category_suggestions; result jsonb; arr jsonb; n integer; same integer; role_name text;
 categories_array uuid[]; generated_content_id uuid; side text; day date:=(now() AT TIME ZONE 'UTC')::date;
BEGIN
 IF action_name IN ('vote_intent','resolve_tilt','cancel_tilt') THEN RETURN api.vote(p,action_name); END IF;
 IF action_name IN ('suggest_category','moderate_suggestion') THEN RAISE EXCEPTION 'EDITORIAL_CATALOG_ONLY'; END IF;
 IF action_name='category_follow' THEN RETURN api.category_follow(p); END IF;
 IF action_name='categories' THEN RETURN api.catalog_json(); END IF;
 IF action_name='ranking' THEN RETURN api.creator_ranking(p); END IF;
 IF action_name='category_rankings' THEN RETURN api.catalog_rankings(p); END IF;
 IF action_name='search' THEN
  IF nullif(p->>'categoryId','') IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.categories WHERE id=(p->>'categoryId')::uuid AND status='published') THEN RAISE EXCEPTION 'CATEGORY_NOT_LEAF'; END IF;
  RETURN coalesce((SELECT jsonb_agg(x.item) FROM (SELECT api.content_json(c.id,m.category_id) item FROM public.content_metadata m JOIN public.content_items c ON c.id=m.content_id JOIN public.categories cat ON cat.id=m.category_id JOIN public.content_categories cc ON cc.content_id=m.content_id AND cc.category_id=m.category_id
   WHERE c.moderation_status='approved' AND cc.status='approved' AND cat.status='published' AND api.can_read(c) AND (nullif(p->>'categoryId','') IS NULL OR cc.category_id=(p->>'categoryId')::uuid) AND (m.subject_name ILIKE '%'||(p->>'query')||'%' OR m.reference_url ILIKE '%'||(p->>'query')||'%' OR c.caption ILIKE '%'||(p->>'query')||'%' OR array_to_string(c.tags,' ') ILIKE '%'||(p->>'query')||'%') ORDER BY lower(m.subject_name),c.id LIMIT 24)x),'[]');
 ELSIF action_name='feed' THEN
  RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(x.item) FROM (
   SELECT api.content_json(c.id,cc.category_id) item FROM public.content_items c
   JOIN public.content_categories cc ON cc.content_id=c.id JOIN public.categories cat ON cat.id=cc.category_id
   WHERE c.moderation_status='approved' AND cc.status='approved' AND cat.status='published' AND api.can_read(c)
   AND (nullif(p->>'categoryId','') IS NULL OR cc.category_id=(p->>'categoryId')::uuid)
   AND (coalesce(p->>'mode','for_you')<>'following' OR (EXISTS(SELECT 1 FROM public.follows WHERE follower_id=u AND followed_id=c.author_id) OR EXISTS(SELECT 1 FROM public.category_follows f WHERE f.user_id=u AND f.category_id=cc.category_id)))
   ORDER BY md5(c.id::text||cc.category_id::text||coalesce(p->>'seed','votilt'))
   LIMIT least(15,greatest(1,coalesce((p->>'limit')::integer,12))) OFFSET least(100000,greatest(0,coalesce((p->>'offset')::integer,0)))
  ) x),'[]'));
 ELSIF action_name='content' THEN
  cat:=coalesce(nullif(p->>'categoryId','')::uuid,(SELECT cc.category_id FROM public.content_categories cc JOIN public.content_items c ON c.id=cc.content_id WHERE cc.content_id=(p->>'contentId')::uuid AND (cc.status='approved' OR c.author_id=u OR api.is_mod()) ORDER BY cc.category_id LIMIT 1));
  result:=api.content_json((p->>'contentId')::uuid,cat);
  IF result IS NULL THEN RAISE EXCEPTION 'CONTENT_UNAVAILABLE'; END IF;
  RETURN result||jsonb_build_object('categories',coalesce((SELECT jsonb_agg(jsonb_build_object('id',c.id,'title',c.title)) FROM public.content_categories cc JOIN public.categories c ON c.id=cc.category_id JOIN public.content_items author_item ON author_item.id=cc.content_id WHERE cc.content_id=(p->>'contentId')::uuid AND cc.status IN ('approved','pending') AND (cc.status='approved' OR author_item.author_id=u OR api.is_mod()) AND c.status='published'),'[]'));
 ELSIF action_name='profile' THEN
  target:=(p->>'userId')::uuid;
  IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target AND NOT suspended AND NOT api.blocked(u,id)
   AND (visibility='public' OR id=u OR (visibility='friends' AND api.friends(id,u)))) THEN RAISE EXCEPTION 'PROFILE_UNAVAILABLE'; END IF;
  SELECT to_jsonb(pr)||jsonb_build_object('isFollowing',EXISTS(SELECT 1 FROM public.follows WHERE follower_id=u AND followed_id=target),
   'isFriend',api.friends(u,target),'contentCount',(SELECT count(*) FROM public.content_items WHERE author_id=target AND moderation_status='approved'),
   'followerCount',(SELECT count(*) FROM public.follows WHERE followed_id=target)) INTO result FROM public.profiles pr WHERE id=target;
  RETURN result||api.creator_profile(target);
 ELSIF action_name='daily' THEN
  SELECT d.category_id INTO cat FROM public.daily_challenges d JOIN public.categories c ON c.id=d.category_id WHERE d.date_utc=day AND c.status='published' AND EXISTS(SELECT 1 FROM public.content_categories cc JOIN public.content_items daily_content ON daily_content.id=cc.content_id JOIN public.profiles author ON author.id=daily_content.author_id WHERE cc.category_id=c.id AND cc.status='approved' AND daily_content.moderation_status='approved' AND daily_content.visibility='public' AND NOT author.suspended);
  IF cat IS NULL THEN SELECT c.id INTO cat FROM public.categories c WHERE c.status='published' AND EXISTS(SELECT 1 FROM public.content_categories cc JOIN public.content_items daily_content ON daily_content.id=cc.content_id JOIN public.profiles author ON author.id=daily_content.author_id WHERE cc.category_id=c.id AND cc.status='approved' AND daily_content.moderation_status='approved' AND daily_content.visibility='public' AND NOT author.suspended) ORDER BY md5(c.id::text||day::text) LIMIT 1; END IF;
  RETURN jsonb_build_object('dateUtc',day,'categoryId',cat,'title',(SELECT title FROM public.categories WHERE id=cat));
 ELSIF action_name='quiz' THEN
  RETURN jsonb_build_object('items',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'mediaUrl','/quiz-media/'||id))
   FROM private.quiz_items WHERE enabled AND NOT test_only),'[]'),'message','Servono fotografie reali con provenienza verificata. Il quiz aprirà quando il catalogo sarà pronto.');
 END IF;
 IF u IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT suspended) THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 IF action_name='me' THEN
  RETURN (SELECT to_jsonb(pr)||jsonb_build_object('settings',to_jsonb(s),'role',r.role,
   'interests',coalesce((SELECT jsonb_agg(category_id) FROM public.user_category_interests WHERE user_id=u),'[]'))
   FROM public.profiles pr JOIN public.profile_settings s ON s.user_id=pr.id JOIN public.user_roles r ON r.user_id=pr.id WHERE pr.id=u);
 ELSIF action_name='champions' THEN
  target:=coalesce((p->>'userId')::uuid,u);
  IF target<>u AND (api.blocked(u,target) OR NOT EXISTS(SELECT 1 FROM public.profile_settings WHERE user_id=target AND (show_champions='public' OR (show_champions='friends' AND api.friends(u,target))))) THEN RAISE EXCEPTION 'CHAMPIONS_PRIVATE'; END IF;
  RETURN coalesce((SELECT jsonb_agg(api.content_json(s.champion_content_id,s.category_id)||jsonb_build_object('slotVersion',s.version) ORDER BY c.title)
   FROM public.vote_slots s JOIN public.categories c ON c.id=s.category_id WHERE s.user_id=target AND s.champion_content_id IS NOT NULL
   AND api.content_json(s.champion_content_id,s.category_id) IS NOT NULL),'[]');
 ELSIF action_name='duel' THEN
  RETURN (SELECT to_jsonb(d)||jsonb_build_object('incumbent',api.content_json(incumbent_id,category_id),'challenger',api.content_json(challenger_id,category_id))
   FROM public.tilt_duels d WHERE id=(p->>'duelId')::uuid AND user_id=u);
 ELSIF action_name='history' THEN
  RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT d.id,d.category_id,d.status,d.winner_side,d.created_at,c.title category_title
   FROM public.tilt_duels d JOIN public.categories c ON c.id=d.category_id WHERE d.user_id=u ORDER BY created_at DESC LIMIT 50)x),'[]');
 ELSIF action_name='notifications' THEN
  RETURN coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM public.notifications WHERE recipient_id=u ORDER BY created_at DESC LIMIT 50)x),'[]');
 ELSIF action_name='social' THEN
  RETURN jsonb_build_object('people',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (
    SELECT pr.id,pr.handle,pr.display_name,pr.bio,api.friends(u,pr.id) is_friend,
    EXISTS(SELECT 1 FROM public.follows WHERE follower_id=u AND followed_id=pr.id) is_following
    FROM public.profiles pr WHERE pr.id<>u AND NOT pr.suspended AND NOT api.blocked(u,pr.id)
    AND (pr.visibility='public' OR (pr.visibility='friends' AND api.friends(u,pr.id))) AND (coalesce(p->>'search','')='' OR pr.handle ILIKE '%'||(p->>'search')||'%')
    ORDER BY pr.handle LIMIT 30)x),'[]'),
    'requests',coalesce((SELECT jsonb_agg(to_jsonb(fr)||jsonb_build_object('handle',pr.handle)) FROM public.friend_requests fr
      JOIN public.profiles pr ON pr.id=fr.requester_id WHERE fr.recipient_id=u AND fr.status='pending' AND NOT api.blocked(u,pr.id)),'[]'),
    'outgoing',coalesce((SELECT jsonb_agg(recipient_id) FROM public.friend_requests WHERE requester_id=u AND status='pending'),'[]'));
 ELSIF action_name='taste_match' THEN
  target:=(p->>'userId')::uuid;
  IF NOT api.can_compare(u,target) THEN RAISE EXCEPTION 'CHAMPIONS_PRIVATE'; END IF;
  SELECT count(*),count(*) FILTER(WHERE (SELECT author_id FROM public.content_items WHERE id=a.champion_content_id)=(SELECT author_id FROM public.content_items WHERE id=b.champion_content_id)) INTO n,same
   FROM public.vote_slots a JOIN public.vote_slots b USING(category_id) WHERE a.user_id=u AND b.user_id=target
   AND a.champion_content_id IS NOT NULL AND b.champion_content_id IS NOT NULL;
  RETURN jsonb_build_object('common',n,'same',same,'percentage',CASE WHEN n>=3 THEN round(100.0*same/n) ELSE NULL END);
 ELSIF action_name='my_uploads' THEN
  RETURN coalesce((SELECT jsonb_agg(api.content_json(id,NULL) ORDER BY created_at DESC) FROM public.content_items WHERE author_id=u AND moderation_status<>'removed'),'[]');
 ELSIF action_name='moderation' THEN
  IF NOT api.is_mod() THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  RETURN jsonb_build_object('contents',coalesce((SELECT jsonb_agg(api.content_json(id,NULL) ORDER BY created_at) FROM public.content_items WHERE moderation_status=coalesce(p->>'status','pending_review') AND api.can_read(content_items)),'[]'),
   'users',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'handle',handle,'suspended',suspended)) FROM (SELECT id,handle,suspended FROM public.profiles WHERE length(coalesce(p->>'search',''))>=2 AND handle ILIKE '%'||(p->>'search')||'%' ORDER BY handle LIMIT 15)x),'[]'),
   'reports',coalesce((SELECT jsonb_agg(to_jsonb(r)) FROM public.reports r WHERE status='pending'),'[]'),
   'suggestions',coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM public.category_suggestions s WHERE status='pending'),'[]'),
   'audit',coalesce((SELECT jsonb_agg(to_jsonb(x)) FROM (SELECT * FROM public.moderation_actions ORDER BY created_at DESC LIMIT 30)x),'[]'));
 ELSIF action_name='my_suggestions' THEN
  RETURN coalesce((SELECT jsonb_agg(to_jsonb(s)) FROM public.category_suggestions s WHERE proposer_id=u),'[]');
 ELSIF action_name='battle' THEN
  SELECT recipient_id,category_id INTO target,cat FROM public.battle_shares
   WHERE id=(p->>'battleId')::uuid AND (creator_id=u OR recipient_id=u) AND NOT revoked AND expires_at>now();
  IF target=u THEN SELECT creator_id INTO target FROM public.battle_shares WHERE id=(p->>'battleId')::uuid; END IF;
  IF target IS NULL THEN RAISE EXCEPTION 'INVITE_UNAVAILABLE'; END IF;
  IF NOT api.can_compare(u,target) THEN RAISE EXCEPTION 'CHAMPIONS_PRIVATE'; END IF;
  RETURN jsonb_build_object('categoryId',cat,'mine',(SELECT api.content_json(champion_content_id,cat) FROM public.vote_slots WHERE user_id=u AND category_id=cat),
    'friend',(SELECT api.content_json(champion_content_id,cat) FROM public.vote_slots WHERE user_id=target AND category_id=cat));
 END IF;

 PERFORM pg_advisory_xact_lock(8815001);
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT suspended) THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 IF action_name='settings' THEN
  UPDATE public.profile_settings SET show_champions=coalesce(p->>'showChampions',show_champions),
   allow_comparison=coalesce((p->>'allowComparison')::boolean,allow_comparison),haptics=coalesce((p->>'haptics')::boolean,haptics),
   reduce_motion=coalesce((p->>'reduceMotion')::boolean,reduce_motion) WHERE user_id=u;
 ELSIF action_name='interests' THEN
  SELECT array_agg(value::uuid) INTO categories_array FROM jsonb_array_elements_text(p->'categoryIds');
  IF cardinality(categories_array)>50 OR EXISTS(SELECT 1 FROM unnest(categories_array)x WHERE NOT EXISTS(SELECT 1 FROM public.categories WHERE id=x AND status='published')) THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  DELETE FROM public.user_category_interests WHERE user_id=u;
  INSERT INTO public.user_category_interests SELECT u,x FROM unnest(categories_array)x ON CONFLICT DO NOTHING;
  UPDATE public.profile_settings SET onboarding_complete=true WHERE user_id=u;
 ELSIF action_name='profile_update' THEN
  UPDATE public.profiles SET display_name=coalesce(p->>'displayName',display_name),bio=coalesce(p->>'bio',bio),visibility=coalesce(p->>'visibility',visibility) WHERE id=u;
 ELSIF action_name IN ('follow_toggle','friend_request','block') THEN
  target:=(p->>'userId')::uuid;
  IF target=u OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target AND NOT suspended) THEN RAISE EXCEPTION 'PROFILE_UNAVAILABLE'; END IF;
  IF action_name<>'block' AND api.blocked(u,target) THEN RAISE EXCEPTION 'PROFILE_UNAVAILABLE'; END IF;
  IF action_name='follow_toggle' THEN
   IF coalesce((p->>'following')::boolean,NOT EXISTS(SELECT 1 FROM public.follows WHERE follower_id=u AND followed_id=target)) THEN
    INSERT INTO public.follows VALUES(u,target) ON CONFLICT DO NOTHING;
   ELSE DELETE FROM public.follows WHERE follower_id=u AND followed_id=target; END IF;
  ELSIF action_name='friend_request' THEN
   IF NOT api.friends(u,target) AND NOT EXISTS(SELECT 1 FROM public.friend_requests WHERE least(requester_id,recipient_id)=least(u,target) AND greatest(requester_id,recipient_id)=greatest(u,target) AND status='pending') THEN
    INSERT INTO public.friend_requests(requester_id,recipient_id) VALUES(u,target);
    INSERT INTO public.notifications(recipient_id,type,title,entity_id) VALUES(target,'friend_request','Hai una nuova richiesta di amicizia',u);
   END IF;
  ELSE
   INSERT INTO public.user_blocks VALUES(u,target) ON CONFLICT DO NOTHING;
   DELETE FROM public.follows WHERE (follower_id=u AND followed_id=target) OR (follower_id=target AND followed_id=u);
   DELETE FROM public.friendships WHERE user_low_id=least(u,target) AND user_high_id=greatest(u,target);
   UPDATE public.friend_requests SET status='cancelled' WHERE status='pending' AND least(requester_id,recipient_id)=least(u,target) AND greatest(requester_id,recipient_id)=greatest(u,target);
   INSERT INTO public.vote_events(user_id,category_id,kind,old_content_id)
    SELECT s.user_id,s.category_id,'invalidated',s.champion_content_id FROM public.vote_slots s JOIN public.content_items c ON c.id=s.champion_content_id
    WHERE (s.user_id=u AND c.author_id=target) OR (s.user_id=target AND c.author_id=u);
   UPDATE public.vote_slots s SET champion_content_id=NULL,version=version+1,updated_at=now() FROM public.content_items c
    WHERE c.id=s.champion_content_id AND ((s.user_id=u AND c.author_id=target) OR (s.user_id=target AND c.author_id=u));
   UPDATE public.tilt_duels d SET status='stale' WHERE d.status='pending' AND EXISTS(SELECT 1 FROM public.content_items c
    WHERE c.id IN(d.incumbent_id,d.challenger_id) AND ((d.user_id=u AND c.author_id=target) OR (d.user_id=target AND c.author_id=u)));
  END IF;
 ELSIF action_name='friend_answer' THEN
  SELECT * INTO req FROM public.friend_requests WHERE id=(p->>'requestId')::uuid AND recipient_id=u AND status='pending' FOR UPDATE;
  IF NOT FOUND OR api.blocked(u,req.requester_id) THEN RAISE EXCEPTION 'REQUEST_UNAVAILABLE'; END IF;
  IF coalesce((p->>'accept')::boolean,false) THEN
   UPDATE public.friend_requests SET status='accepted' WHERE id=req.id;
   INSERT INTO public.friendships VALUES(least(u,req.requester_id),greatest(u,req.requester_id)) ON CONFLICT DO NOTHING;
   INSERT INTO public.notifications(recipient_id,type,title,entity_id) VALUES(req.requester_id,'friend_accepted','La tua richiesta di amicizia è stata accettata',u);
  ELSE UPDATE public.friend_requests SET status='rejected' WHERE id=req.id; END IF;
 ELSIF action_name='report' THEN
  cid:=(p->>'contentId')::uuid;
  IF api.content_json(cid,NULL) IS NULL THEN RAISE EXCEPTION 'CONTENT_UNAVAILABLE'; END IF;
  IF (SELECT count(*) FROM public.reports WHERE reporter_id=u AND created_at>now()-interval '1 hour')>=20 THEN RAISE EXCEPTION 'RATE_LIMITED'; END IF;
  INSERT INTO public.reports(reporter_id,content_id,reason) VALUES(u,cid,p->>'reason') ON CONFLICT(reporter_id,content_id) DO NOTHING;
 ELSIF action_name='suspend_user' THEN
  IF NOT api.is_mod() THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  target:=(p->>'userId')::uuid;
  IF target=u OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=target AND role<>'user') THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=target) THEN RAISE EXCEPTION 'PROFILE_UNAVAILABLE'; END IF;
  IF length(coalesce(p->>'reason',''))<3 OR NOT p ? 'suspended' THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  IF EXISTS(SELECT 1 FROM public.profiles WHERE id=target AND suspended=(p->>'suspended')::boolean) THEN RETURN jsonb_build_object('ok',true); END IF;
  UPDATE public.profiles SET suspended=(p->>'suspended')::boolean WHERE id=target;
  IF (p->>'suspended')::boolean THEN
   FOR generated_content_id IN SELECT id FROM public.content_items WHERE author_id=target ORDER BY id LOOP PERFORM api.invalidate_content(generated_content_id); END LOOP;
   INSERT INTO public.vote_events(user_id,category_id,kind,old_content_id) SELECT user_id,category_id,'invalidated',champion_content_id FROM public.vote_slots WHERE user_id=target AND champion_content_id IS NOT NULL;
   UPDATE public.vote_slots SET champion_content_id=NULL,version=version+1,updated_at=now() WHERE user_id=target AND champion_content_id IS NOT NULL;
   UPDATE public.tilt_duels SET status='stale' WHERE user_id=target AND status='pending';
   DELETE FROM private.sessions WHERE user_id=target;
  END IF;
  INSERT INTO public.moderation_actions(moderator_id,target_id,action,reason) VALUES(u,target,CASE WHEN (p->>'suspended')::boolean THEN 'suspend_user' ELSE 'restore_user' END,p->>'reason');
 ELSIF action_name IN ('moderate','delete_content') THEN
  cid:=(p->>'contentId')::uuid;
  SELECT * INTO item FROM public.content_items WHERE id=cid FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'CONTENT_UNAVAILABLE'; END IF;
  IF action_name='delete_content' THEN
   IF item.author_id<>u THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
   side:='removed';
  ELSE
   IF NOT api.is_mod() THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
   side:=p->>'decision';
   IF side NOT IN ('approved','rejected','hidden') OR length(coalesce(p->>'reason',''))<3 THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
   IF item.moderation_status='draft' OR item.moderation_status='removed' THEN RAISE EXCEPTION 'INVALID_STATE'; END IF;
  END IF;
  IF side='approved' AND EXISTS(SELECT 1 FROM public.content_categories cc JOIN public.categories rules ON rules.id=cc.category_id LEFT JOIN public.content_metadata m ON m.content_id=cc.content_id AND m.category_id=cc.category_id WHERE cc.content_id=cid AND (m.subject_name IS NULL OR trim(m.subject_name)='' OR (rules.requires_url AND nullif(m.reference_url,'') IS NULL))) THEN RAISE EXCEPTION 'METADATA_REQUIRED'; END IF;
  IF item.moderation_status=side THEN RETURN jsonb_build_object('ok',true); END IF;
  IF side IN ('hidden','removed','rejected') THEN PERFORM api.invalidate_content(cid); END IF;
  UPDATE public.content_items SET moderation_status=side,review_reason=coalesce(p->>'reason','Ritirato dall’autore'),
    approved_at=CASE WHEN side='approved' THEN now() ELSE approved_at END WHERE id=cid;
  UPDATE public.content_categories SET status=CASE WHEN side='approved' THEN 'approved' ELSE status END WHERE content_id=cid AND status<>'rejected';
  INSERT INTO public.moderation_actions(moderator_id,target_id,action,reason) VALUES(u,cid,side,coalesce(p->>'reason','Ritiro autore'));
  INSERT INTO public.notifications(recipient_id,type,title,entity_id) VALUES(item.author_id,'content_review',CASE WHEN side='approved' THEN 'Il tuo contenuto è stato approvato' ELSE 'Lo stato del tuo contenuto è cambiato' END,cid);
  UPDATE public.reports SET status='reviewed' WHERE content_id=cid AND status='pending';
 ELSIF action_name='dismiss_report' THEN
  IF NOT api.is_mod() THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  UPDATE public.reports SET status='dismissed' WHERE id=(p->>'reportId')::uuid;
  INSERT INTO public.moderation_actions(moderator_id,target_id,action,reason) VALUES(u,(p->>'reportId')::uuid,'dismiss_report',p->>'reason');
 ELSIF action_name='mark_notification' THEN
  UPDATE public.notifications SET read_at=now() WHERE recipient_id=u AND (p->>'notificationId' IS NULL OR id=(p->>'notificationId')::uuid);
 ELSIF action_name='delete_notification' THEN
  DELETE FROM public.notifications WHERE recipient_id=u AND id=(p->>'notificationId')::uuid;
 ELSIF action_name='suggest_category' THEN
  IF (SELECT count(*) FROM public.category_suggestions WHERE proposer_id=u AND created_at>now()-interval '1 day')>=5 THEN RAISE EXCEPTION 'RATE_LIMITED'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=(p->>'parentId')::uuid AND depth=3 AND status='published') THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  INSERT INTO public.category_suggestions(proposer_id,parent_id,title,description,examples,reference_kind) VALUES(u,(p->>'parentId')::uuid,p->>'title',p->>'description',p->'examples',coalesce(p->>'referenceKind','name'));
 ELSIF action_name='moderate_suggestion' THEN
  IF NOT api.is_mod() THEN RAISE EXCEPTION 'FORBIDDEN'; END IF;
  SELECT * INTO suggestion FROM public.category_suggestions WHERE id=(p->>'suggestionId')::uuid AND status='pending' FOR UPDATE;
  IF NOT FOUND THEN RAISE EXCEPTION 'REQUEST_UNAVAILABLE'; END IF;
  IF p->>'decision' NOT IN ('approved','rejected') OR length(coalesce(p->>'reason',''))<3 THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  UPDATE public.category_suggestions SET status=p->>'decision',review_reason=p->>'reason' WHERE id=suggestion.id;
  IF p->>'decision'='approved' THEN
   INSERT INTO public.categories(id,parent_id,depth,slug,title,description,reference_kind,reference_label,requires_url,allowed_kinds) VALUES(gen_random_uuid(),suggestion.parent_id,4,
     lower(regexp_replace(suggestion.title,'[^a-zA-Z0-9]+','-','g'))||'-'||left(suggestion.id::text,6),suggestion.title,suggestion.description,suggestion.reference_kind,
     CASE suggestion.reference_kind WHEN 'person' THEN 'Nome della persona' WHEN 'website' THEN 'Nome del sito' WHEN 'place' THEN 'Nome del luogo' WHEN 'tool' THEN 'Nome dello strumento' ELSE 'Nome della creazione' END,suggestion.reference_kind IN ('website','tool'),CASE WHEN suggestion.reference_kind='tool' THEN ARRAY['ai_tool'] ELSE ARRAY['photo','illustration','ai_art'] END);
  END IF;
  INSERT INTO public.moderation_actions(moderator_id,target_id,action,reason) VALUES(u,suggestion.id,'category_'||(p->>'decision'),p->>'reason');
 ELSIF action_name='create_battle' THEN
  target:=(p->>'userId')::uuid; cat:=(p->>'categoryId')::uuid;
  IF NOT api.can_compare(u,target) THEN RAISE EXCEPTION 'CHAMPIONS_PRIVATE'; END IF;
  IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=cat AND status='published') THEN RAISE EXCEPTION 'CATEGORY_NOT_LEAF'; END IF;
  INSERT INTO public.battle_shares(creator_id,recipient_id,category_id) VALUES(u,target,cat) RETURNING id INTO generated_content_id;
  INSERT INTO public.notifications(recipient_id,type,title,entity_id) VALUES(target,'battle','Un amico ti ha invitato a una Friends Battle',generated_content_id);
  RETURN jsonb_build_object('id',generated_content_id,'url','votilt://battle/'||generated_content_id);
 ELSIF action_name='revoke_battle' THEN
  UPDATE public.battle_shares SET revoked=true WHERE id=(p->>'battleId')::uuid AND creator_id=u;
 ELSIF action_name='quiz_answer' THEN
  IF p->>'answer' NOT IN ('REAL','AI') THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
  IF NOT EXISTS(SELECT 1 FROM private.quiz_items WHERE id=(p->>'quizId')::uuid AND enabled AND NOT test_only) THEN RAISE EXCEPTION 'QUIZ_UNAVAILABLE'; END IF;
  INSERT INTO public.real_ai_answers SELECT u,id,p->>'answer',ground_truth=p->>'answer',now() FROM private.quiz_items WHERE id=(p->>'quizId')::uuid ON CONFLICT DO NOTHING;
  RETURN (SELECT jsonb_build_object('correct',a.is_correct,'answer',a.answer,'groundTruth',q.ground_truth,'evidence',q.evidence_note)
   FROM public.real_ai_answers a JOIN private.quiz_items q ON q.id=a.quiz_item_id WHERE a.user_id=u AND q.id=(p->>'quizId')::uuid);
 ELSIF action_name='delete_account' THEN
  IF p->>'confirmation' IS DISTINCT FROM 'ELIMINA' THEN RAISE EXCEPTION 'CONFIRMATION_REQUIRED'; END IF;
  UPDATE public.content_items SET moderation_status='removed' WHERE author_id=u;
  FOR generated_content_id IN SELECT id FROM public.content_items WHERE author_id=u ORDER BY id LOOP PERFORM api.invalidate_content(generated_content_id); END LOOP;
  DELETE FROM public.profiles WHERE id=u;
 ELSIF action_name='impression' THEN
  cid:=(p->>'contentId')::uuid; cat:=(p->>'categoryId')::uuid;
  PERFORM api.validate_candidate(cid,cat);
  INSERT INTO public.content_impressions(user_id,content_id,category_id,session_id) VALUES(u,cid,cat,(p->>'sessionId')::uuid) ON CONFLICT DO NOTHING;
 ELSE RAISE EXCEPTION 'INVALID_ACTION'; END IF;
 RETURN jsonb_build_object('ok',true);
END $$;

CREATE OR REPLACE FUNCTION api.create_upload(p jsonb) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE u uuid:=api.uid(); cat uuid; cid uuid:=(p->>'id')::uuid; kind_name text:=p->>'kind'; ref jsonb; rule public.categories;
BEGIN
 IF u IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(8815001);
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT suspended) THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 IF (SELECT count(*) FROM public.content_items WHERE author_id=u AND created_at>now()-interval '1 day')>=30 THEN RAISE EXCEPTION 'RATE_LIMITED'; END IF;
 IF jsonb_array_length(p->'categoryIds')<>1 OR p->>'rights'<>'true' OR p->>'adultConsent'<>'true' THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
 IF p->>'filename'<>cid::text||'.jpg' THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
 INSERT INTO public.content_items(id,author_id,kind,title,caption,media_path,provenance,moderation_status,rights_attested,adult_consent,byte_size,mime_type,width,height,visibility)
 VALUES(cid,u,kind_name,p->>'title',p->>'caption',p->>'filename',p->>'provenance','pending_review',true,true,(p->>'size')::integer,'image/jpeg',(p->>'width')::integer,(p->>'height')::integer,coalesce(p->>'visibility','public'));
 IF jsonb_array_length(coalesce(p->'tags','[]'::jsonb))>20 OR EXISTS(SELECT 1 FROM jsonb_array_elements_text(coalesce(p->'tags','[]'::jsonb)) tag WHERE length(tag) NOT BETWEEN 1 AND 40 OR tag COLLATE "unicode" !~ '^[[:alnum:] _-]+$') THEN RAISE EXCEPTION 'INVALID_INPUT'; END IF;
 UPDATE public.content_items SET tags=ARRAY(SELECT DISTINCT value FROM jsonb_array_elements_text(coalesce(p->'tags','[]'::jsonb))) WHERE id=cid;
 FOR cat IN SELECT value::uuid FROM jsonb_array_elements_text(p->'categoryIds') LOOP
  SELECT * INTO rule FROM public.categories WHERE id=cat AND status='published';
  IF NOT FOUND THEN RAISE EXCEPTION 'CATEGORY_NOT_LEAF'; END IF;
  IF NOT kind_name=ANY(rule.allowed_kinds) THEN RAISE EXCEPTION 'INVALID_CONTENT_KIND'; END IF;
  ref:=p->'metadata'->cat::text;
  IF length(trim(coalesce(ref->>'name','')))=0 THEN RAISE EXCEPTION 'METADATA_REQUIRED'; END IF;
  IF rule.requires_url AND (nullif(ref->>'url','') IS NULL OR ref->>'url' !~ '^https?://[^[:space:]@]+$') THEN RAISE EXCEPTION 'INVALID_REFERENCE_URL'; END IF;
  INSERT INTO public.content_categories(content_id,category_id,status) VALUES(cid,cat,'pending');
  INSERT INTO public.content_metadata VALUES(cid,cat,trim(ref->>'name'),nullif(ref->>'url',''));
 END LOOP;
END $$;

CREATE OR REPLACE FUNCTION api.feed_candidates(p jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(x)),'[]') FROM (
  SELECT c.id,cc.category_id AS "categoryId",
   EXISTS(WITH RECURSIVE lineage AS(SELECT id,parent_id FROM public.categories WHERE id=cc.category_id UNION ALL SELECT cat.id,cat.parent_id FROM public.categories cat JOIN lineage l ON l.parent_id=cat.id)
    SELECT 1 FROM public.user_category_interests i JOIN lineage l ON l.id=i.category_id WHERE i.user_id=api.uid()) interested,
   ((SELECT count(*) FROM public.content_impressions WHERE content_id=c.id)<3 OR c.approved_at>now()-interval '7 days') fresh,
   EXISTS(SELECT 1 FROM (SELECT content_id,category_id FROM public.content_impressions WHERE user_id=api.uid() ORDER BY seen_at DESC LIMIT 100) recent WHERE recent.content_id=c.id AND recent.category_id=cc.category_id) seen
  FROM public.content_items c JOIN public.content_categories cc ON cc.content_id=c.id JOIN public.categories cat ON cat.id=cc.category_id
  WHERE c.moderation_status='approved' AND cc.status='approved' AND cat.status='published' AND api.can_read(c)
   AND (nullif(p->>'categoryId','') IS NULL OR cc.category_id=(p->>'categoryId')::uuid)
   AND (coalesce(p->>'mode','for_you')<>'following' OR (EXISTS(SELECT 1 FROM public.follows WHERE follower_id=api.uid() AND followed_id=c.author_id) OR EXISTS(SELECT 1 FROM public.category_follows f WHERE f.user_id=api.uid() AND f.category_id=cc.category_id)))
  ORDER BY md5(c.id::text||cc.category_id::text||coalesce(p->>'seed','votilt')) LIMIT 600
 )x $$;
CREATE OR REPLACE FUNCTION api.feed_items(p jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT coalesce(jsonb_agg(api.content_json(c.id,(e.value->>'categoryId')::uuid) ORDER BY e.ordinality),'[]')
 FROM jsonb_array_elements(p) WITH ORDINALITY e(value,ordinality) JOIN public.content_items c ON c.id=(e.value->>'id')::uuid
 JOIN public.content_categories cc ON cc.content_id=c.id AND cc.category_id=(e.value->>'categoryId')::uuid
 JOIN public.categories cat ON cat.id=cc.category_id
 WHERE c.moderation_status='approved' AND cc.status='approved' AND cat.status='published' AND api.can_read(c) $$;

CREATE OR REPLACE FUNCTION api.auth_lookup(p_email text) RETURNS TABLE(user_id uuid,password_hash text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT c.user_id,c.password_hash FROM private.credentials c JOIN public.profiles p ON p.id=c.user_id WHERE c.email=p_email AND NOT p.suspended $$;
CREATE OR REPLACE FUNCTION api.auth_session(p_hash text) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT s.user_id FROM private.sessions s JOIN public.profiles p ON p.id=s.user_id WHERE s.token_hash=p_hash AND s.expires_at>now() AND NOT p.suspended $$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA api FROM PUBLIC;
CREATE OR REPLACE FUNCTION api.quiz_media_path(p_id uuid) RETURNS text LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT media_path FROM private.quiz_items WHERE id=p_id AND enabled AND NOT test_only $$;
REVOKE ALL ON FUNCTION api.quiz_media_path(uuid) FROM PUBLIC;
CREATE OR REPLACE FUNCTION api.upload_receipt(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE u uuid:=api.uid(); op uuid:=(p->>'clientOperationId')::uuid; fingerprint text:=md5((p-'id'-'filename')::text); receipt public.operation_receipts; result jsonb;
BEGIN
 IF u IS NULL OR op IS NULL THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(8815001);
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT suspended) THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 SELECT * INTO receipt FROM public.operation_receipts WHERE user_id=u AND operation_id=op AND action='upload';
 IF FOUND THEN
  IF receipt.fingerprint<>fingerprint THEN RAISE EXCEPTION 'IDEMPOTENCY_KEY_REUSE'; END IF;
  RETURN receipt.result_json;
 END IF;
 PERFORM api.create_upload(p);
 result:=jsonb_build_object('id',p->>'id','status','pending_review');
 INSERT INTO public.operation_receipts VALUES(u,op,'upload',fingerprint,result,now());
 RETURN result;
END $$;
REVOKE ALL ON FUNCTION api.upload_receipt(jsonb) FROM PUBLIC;
CREATE OR REPLACE FUNCTION api.media_referenced(p_filename text) RETURNS boolean LANGUAGE plpgsql VOLATILE SECURITY DEFINER SET search_path=public,pg_temp AS $$
BEGIN
 PERFORM pg_advisory_xact_lock(8815001);
 RETURN EXISTS(SELECT 1 FROM public.content_items WHERE media_path=p_filename);
END $$;
REVOKE ALL ON FUNCTION api.media_referenced(text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION api.revoke_session(p_hash text) RETURNS void LANGUAGE sql SECURITY DEFINER SET search_path=public,pg_temp AS $$
 DELETE FROM private.sessions WHERE token_hash=p_hash $$;
REVOKE ALL ON FUNCTION api.revoke_session(text) FROM PUBLIC;
CREATE OR REPLACE FUNCTION api.category_policy_context() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT jsonb_build_object('published',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'title',title,'status','published')) FROM public.categories WHERE status='published'),'[]'),
 'pending',coalesce((SELECT jsonb_agg(jsonb_build_object('id',id,'title',title,'description',description,'examples',examples,'status','pending','proposerId',proposer_id)) FROM public.category_suggestions WHERE status='pending'),'[]')) $$;
REVOKE ALL ON FUNCTION api.category_policy_context() FROM PUBLIC;

CREATE OR REPLACE FUNCTION api.search_text(value text) RETURNS text LANGUAGE sql IMMUTABLE AS $$
 SELECT lower(translate(coalesce(value,''),'àáâäãåèéêëìíîïòóôöõùúûüçÀÁÂÄÃÅÈÉÊËÌÍÎÏÒÓÔÖÕÙÚÛÜÇ#','aaaaaaeeeeiiiiooooouuuucAAAAAAEEEEIIIIOOOOOUUUUC')) $$;

-- Creator preferences retain an image as evidence, never as a second vote.
CREATE OR REPLACE FUNCTION api.category_path(cat uuid) RETURNS text[] LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH RECURSIVE lineage AS (
  SELECT id,parent_id,title,depth FROM public.categories WHERE id=cat AND status='published'
  UNION ALL SELECT c.id,c.parent_id,c.title,c.depth FROM public.categories c JOIN lineage l ON c.id=l.parent_id WHERE c.status='published' AND c.depth<l.depth
 ) SELECT coalesce(array_agg(title ORDER BY depth),ARRAY[]::text[]) FROM lineage $$;

CREATE OR REPLACE FUNCTION api.catalog_json() RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT coalesce(jsonb_agg(to_jsonb(c)||jsonb_build_object('path',api.category_path(c.id),'terminal',NOT EXISTS(SELECT 1 FROM public.categories ch WHERE ch.parent_id=c.id AND ch.status='published'),'isFollowing',EXISTS(SELECT 1 FROM public.category_follows f WHERE f.user_id=api.uid() AND f.category_id=c.id)) ORDER BY CASE WHEN c.slug LIKE 'editorial-%' THEN 0 ELSE 1 END,c.sort_order,c.title),'[]') FROM public.categories c WHERE c.status='published' $$;

CREATE OR REPLACE FUNCTION api.preference_active(slot public.vote_slots) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT EXISTS(SELECT 1 FROM public.content_items c
 JOIN public.content_categories cc ON cc.content_id=c.id AND cc.category_id=slot.category_id AND cc.status='approved'
 JOIN public.categories cat ON cat.id=cc.category_id AND cat.status='published'
 JOIN public.content_metadata m ON m.content_id=c.id AND m.category_id=cat.id
 JOIN public.profiles author ON author.id=c.author_id AND NOT author.suspended
 JOIN public.profiles voter ON voter.id=slot.user_id AND NOT voter.suspended
 WHERE c.id=slot.champion_content_id AND c.moderation_status='approved' AND c.kind=ANY(cat.allowed_kinds)
 AND trim(m.subject_name)<>'' AND (NOT cat.requires_url OR nullif(m.reference_url,'') IS NOT NULL)
 AND NOT api.blocked(slot.user_id,c.author_id)
 AND (c.visibility='public' OR slot.user_id=c.author_id OR (c.visibility='friends' AND api.friends(slot.user_id,c.author_id)))) $$;

CREATE OR REPLACE FUNCTION api.creator_support(creator uuid,cat uuid) RETURNS bigint LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT count(*) FROM public.vote_slots s JOIN public.content_items c ON c.id=s.champion_content_id
 JOIN public.profiles voter ON voter.id=s.user_id AND NOT voter.suspended
 WHERE c.author_id=creator AND s.category_id=cat AND api.preference_active(s) $$;

CREATE OR REPLACE FUNCTION api.creator_representative(creator uuid,cat uuid,viewer uuid,excluded uuid DEFAULT NULL) RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT c.id FROM public.content_items c JOIN public.content_categories cc ON cc.content_id=c.id AND cc.category_id=cat AND cc.status='approved'
 JOIN public.categories rules ON rules.id=cat AND rules.status='published'
 JOIN public.profiles pr ON pr.id=c.author_id AND NOT pr.suspended
 JOIN public.content_metadata m ON m.content_id=c.id AND m.category_id=cat
 WHERE c.author_id=creator AND c.id IS DISTINCT FROM excluded AND c.moderation_status='approved'
 AND NOT api.blocked(viewer,creator) AND (c.visibility='public' OR viewer=creator OR (c.visibility='friends' AND api.friends(viewer,creator)))
 AND c.kind=ANY(rules.allowed_kinds) AND trim(m.subject_name)<>'' AND (NOT rules.requires_url OR nullif(m.reference_url,'') IS NOT NULL)
 ORDER BY c.approved_at DESC NULLS LAST,c.created_at DESC,c.id LIMIT 1 $$;

CREATE OR REPLACE FUNCTION api.creator_ranking(p jsonb) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE cat uuid:=(p->>'categoryId')::uuid; metric text:=coalesce(p->>'metric','popular'); day date:=(now() AT TIME ZONE 'UTC')::date;
BEGIN
 IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=cat AND status='published') THEN RAISE EXCEPTION 'CATEGORY_UNAVAILABLE'; END IF;
 IF metric='trend' AND NOT EXISTS(SELECT 1 FROM public.creator_ranking_snapshots WHERE date_utc=day-7 AND category_id=cat) THEN
  RETURN jsonb_build_object('items','[]'::jsonb,'insufficientHistory',true,'voteModel','creator-v1');
 END IF;
 RETURN jsonb_build_object('items',coalesce((WITH authors AS (
  SELECT DISTINCT c.author_id FROM public.content_items c JOIN public.content_categories cc ON cc.content_id=c.id AND cc.category_id=cat AND cc.status='approved'
  WHERE c.moderation_status='approved' AND api.can_read(c)
 ), scores AS (
  SELECT a.author_id,api.creator_representative(a.author_id,cat,api.uid()) representative,
  api.creator_support(a.author_id,cat) support,coalesce(r.rating,1500) rating,coalesce(r.matches,0) matches,
  api.creator_support(a.author_id,cat)-coalesce(snap.support,0) trend,
  CASE WHEN metric='elo' THEN coalesce(r.rating,1500) WHEN metric='trend' THEN api.creator_support(a.author_id,cat)-coalesce(snap.support,0) ELSE api.creator_support(a.author_id,cat) END score
  FROM authors a LEFT JOIN public.creator_duel_ratings r ON r.author_id=a.author_id AND r.category_id=cat
  LEFT JOIN public.creator_ranking_snapshots snap ON snap.author_id=a.author_id AND snap.category_id=cat AND snap.date_utc=day-7
 ), positions AS (
  SELECT scores.*,rank() OVER(ORDER BY score DESC) position,count(*) FILTER(WHERE support>0) OVER() participants FROM scores WHERE representative IS NOT NULL
 ) SELECT jsonb_agg(x.item ORDER BY x.position,x.author_id) FROM (
  SELECT positions.*,api.content_json(representative,cat)||jsonb_build_object('support',support,'rating',rating,'matches',matches,'trend',trend,'position',position,'participants',participants,'voteModel','creator-v1') item
  FROM positions WHERE coalesce(p->>'query','')='' OR EXISTS(SELECT 1 FROM public.profiles pr WHERE pr.id=author_id AND (pr.handle ILIKE '%'||(p->>'query')||'%' OR pr.display_name ILIKE '%'||(p->>'query')||'%'))
  OR api.content_json(representative,cat)->>'title' ILIKE '%'||(p->>'query')||'%'
  ORDER BY position,author_id LIMIT 100
 ) x),'[]'),'insufficientHistory',false,'voteModel','creator-v1');
END $$;

CREATE OR REPLACE FUNCTION api.catalog_rankings(p jsonb) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH RECURSIVE paths AS (
  SELECT id,parent_id,depth,title,description,ARRAY[title] path,aliases search_aliases FROM public.categories WHERE parent_id IS NULL AND status='published'
  UNION ALL SELECT c.id,c.parent_id,c.depth,c.title,c.description,paths.path||c.title,paths.search_aliases||c.aliases FROM public.categories c JOIN paths ON c.parent_id=paths.id WHERE c.status='published' AND c.depth=paths.depth+1
 ), candidates AS (
  SELECT cat.id,cat.title,cat.description,cat.path,
  (SELECT count(*) FROM public.vote_slots s JOIN public.content_items c ON c.id=s.champion_content_id WHERE s.category_id=cat.id AND api.preference_active(s) AND api.creator_representative(c.author_id,cat.id,api.uid()) IS NOT NULL) "voteCount",
  (SELECT count(*) FROM public.content_categories cc JOIN public.content_items c ON c.id=cc.content_id WHERE cc.category_id=cat.id AND cc.status='approved' AND c.moderation_status='approved' AND api.can_read(c)) "contentCount"
  FROM paths cat WHERE CASE WHEN p ? 'candidateIds' THEN cat.id::text IN (SELECT jsonb_array_elements_text(p->'candidateIds')) ELSE NOT EXISTS(SELECT 1 FROM regexp_split_to_table(trim(coalesce(p->>'query','')),'\s+') term WHERE term<>'' AND api.search_text(array_to_string(cat.path||cat.search_aliases,' ')) NOT LIKE '%'||api.search_text(term)||'%') END
 ), selected AS (
  SELECT * FROM candidates WHERE coalesce(p->>'query','')<>'' OR "voteCount">0 ORDER BY "voteCount" DESC,title,id LIMIT CASE WHEN coalesce(p->>'query','')='' THEN 12 ELSE 100 END
 ) SELECT coalesce(jsonb_agg(to_jsonb(x)||jsonb_build_object('leader',CASE WHEN "voteCount">0 THEN api.creator_ranking(jsonb_build_object('categoryId',id,'metric','popular'))->'items'->0 ELSE NULL END) ORDER BY "voteCount" DESC,title,id),'[]') FROM selected x $$;

CREATE OR REPLACE FUNCTION api.category_follow(p jsonb) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE u uuid:=api.uid(); cat uuid:=(p->>'categoryId')::uuid;
BEGIN
 IF u IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT suspended) THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 PERFORM pg_advisory_xact_lock(8815001);
 IF NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=u AND NOT suspended) THEN RAISE EXCEPTION 'AUTH_REQUIRED'; END IF;
 IF NOT EXISTS(SELECT 1 FROM public.categories WHERE id=cat AND status='published') THEN RAISE EXCEPTION 'CATEGORY_UNAVAILABLE'; END IF;
 IF (p->>'following')::boolean THEN INSERT INTO public.category_follows(user_id,category_id) VALUES(u,cat) ON CONFLICT DO NOTHING;
 ELSE DELETE FROM public.category_follows WHERE user_id=u AND category_id=cat; END IF;
 RETURN jsonb_build_object('ok',true);
END $$;

CREATE OR REPLACE FUNCTION api.creator_profile(creator uuid) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH eligible AS (
  SELECT DISTINCT s.category_id,api.creator_support(creator,s.category_id) preference_count FROM public.vote_slots s JOIN public.content_items c ON c.id=s.champion_content_id
  JOIN public.profiles voter ON voter.id=s.user_id AND NOT voter.suspended
  WHERE c.author_id=creator AND api.preference_active(s) AND api.creator_representative(creator,s.category_id,api.uid()) IS NOT NULL
 ) SELECT jsonb_build_object('preferenceCount',coalesce(sum(preference_count),0),'categoryPreferences',coalesce(jsonb_agg(jsonb_build_object('categoryId',e.category_id,'title',cat.title,'path',api.category_path(e.category_id),'preferences',e.preference_count,'position',(SELECT (item->>'position')::int FROM jsonb_array_elements(api.creator_ranking(jsonb_build_object('categoryId',e.category_id,'metric','popular'))->'items') item WHERE item->>'authorId'=creator::text),'participants',(SELECT (item->>'participants')::int FROM jsonb_array_elements(api.creator_ranking(jsonb_build_object('categoryId',e.category_id,'metric','popular'))->'items') item WHERE item->>'authorId'=creator::text)) ORDER BY e.preference_count DESC,cat.title),'[]')) FROM eligible e JOIN public.categories cat ON cat.id=e.category_id AND cat.status='published' $$;

REVOKE ALL ON ALL FUNCTIONS IN SCHEMA api FROM PUBLIC;

CREATE OR REPLACE FUNCTION api.invalidate_content(cid uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public,pg_temp AS $$
DECLARE slot public.vote_slots; replacement uuid; creator uuid;
BEGIN
 PERFORM pg_advisory_xact_lock(8815001);
 SELECT author_id INTO creator FROM public.content_items WHERE id=cid;
 FOR slot IN SELECT * FROM public.vote_slots WHERE champion_content_id=cid ORDER BY user_id,category_id FOR UPDATE LOOP
  replacement:=api.creator_representative(creator,slot.category_id,slot.user_id,cid);
  IF replacement IS NULL THEN INSERT INTO public.vote_events(user_id,category_id,kind,old_content_id) VALUES(slot.user_id,slot.category_id,'invalidated',cid); END IF;
  UPDATE public.vote_slots SET champion_content_id=replacement,version=version+1,updated_at=now() WHERE user_id=slot.user_id AND category_id=slot.category_id;
 END LOOP;
 UPDATE public.tilt_duels SET status='stale' WHERE status='pending' AND (incumbent_id=cid OR challenger_id=cid);
END $$;

CREATE OR REPLACE FUNCTION api.content_json_image_v0(cid uuid, cat uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 SELECT jsonb_build_object('id',c.id,'title',coalesce((SELECT subject_name FROM public.content_metadata WHERE content_id=c.id AND category_id=cat),c.title),'caption',c.caption,'tags',c.tags,'kind',c.kind,'provenance',c.provenance,
 'status',c.moderation_status,'visibility',c.visibility,'reviewReason',c.review_reason,'authorId',p.id,'handle',p.handle,'displayName',p.display_name,
 'mediaUrl','/media/'||c.id,'categoryId',cat,'categoryTitle',(SELECT title FROM public.categories WHERE id=cat),
 'reference',(SELECT jsonb_build_object('name',m.subject_name,'url',m.reference_url,'label',rules.reference_label,'kind',rules.reference_kind)
   FROM public.content_metadata m JOIN public.categories rules ON rules.id=m.category_id WHERE m.content_id=c.id AND m.category_id=cat),
 'references',coalesce((SELECT jsonb_agg(jsonb_build_object('categoryId',m.category_id,'categoryTitle',rules.title,'name',m.subject_name,'url',m.reference_url,'label',rules.reference_label,'kind',rules.reference_kind,'status',cc.status))
   FROM public.content_metadata m JOIN public.categories rules ON rules.id=m.category_id JOIN public.content_categories cc ON cc.content_id=m.content_id AND cc.category_id=m.category_id
   WHERE m.content_id=c.id AND rules.status='published' AND (cc.status='approved' OR c.author_id=api.uid() OR api.is_mod())),'[]'))
 FROM public.content_items c JOIN public.profiles p ON p.id=c.author_id WHERE c.id=cid AND api.can_read(c)
 AND (cat IS NULL OR EXISTS(SELECT 1 FROM public.content_categories cc JOIN public.categories rules ON rules.id=cc.category_id
 WHERE cc.content_id=c.id AND cc.category_id=cat AND rules.status='published' AND (cc.status='approved' OR c.author_id=api.uid() OR api.is_mod()))) $$;


CREATE OR REPLACE FUNCTION api.content_json(cid uuid, cat uuid DEFAULT NULL) RETURNS jsonb LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public,pg_temp AS $$
 WITH selected AS (SELECT coalesce(cat,(SELECT cc.category_id FROM public.content_categories cc WHERE cc.content_id=cid AND cc.status IN ('approved','pending') ORDER BY cc.category_id LIMIT 1)) category_id), base AS (
 SELECT api.content_json_image_v0(cid,selected.category_id) item,selected.category_id FROM selected)
 SELECT CASE WHEN item IS NULL THEN NULL ELSE item||jsonb_build_object('categoryPath',api.category_path(category_id),'creatorSupport',api.creator_support((item->>'authorId')::uuid,category_id),'originSupport',(SELECT count(*) FROM public.vote_slots s WHERE s.category_id=base.category_id AND s.origin_content_id=cid AND api.preference_active(s)),'voteModel','creator-v1') END FROM base $$;

-- One-time conversion is non-destructive: old image ratings and association rows remain archived.
DO $migration$
BEGIN
 PERFORM pg_advisory_xact_lock(8815001);
 IF NOT EXISTS(SELECT 1 FROM private.model_migrations WHERE name='creator-single-category-v1') THEN
  UPDATE public.vote_slots SET origin_content_id=champion_content_id WHERE origin_content_id IS NULL;
  UPDATE public.tilt_duels SET status='stale' WHERE status='pending';
  INSERT INTO private.legacy_membership_archive(content_id,category_id,membership)
  SELECT content_id,category_id,row_data FROM (
   SELECT cc.*,to_jsonb(cc) row_data,row_number() OVER(PARTITION BY cc.content_id ORDER BY CASE WHEN cc.status='approved' THEN 0 ELSE 1 END,(SELECT count(*) FROM public.vote_slots s WHERE s.champion_content_id=cc.content_id AND s.category_id=cc.category_id) DESC,cc.category_id) ord
   FROM public.content_categories cc WHERE cc.status IN ('approved','pending')) x WHERE ord>1 ON CONFLICT DO NOTHING;
  UPDATE public.content_categories cc SET status='rejected' FROM private.legacy_membership_archive a WHERE a.content_id=cc.content_id AND a.category_id=cc.category_id;
  INSERT INTO public.vote_events(user_id,category_id,kind,old_content_id)
  SELECT s.user_id,s.category_id,'invalidated',s.champion_content_id FROM public.vote_slots s JOIN public.content_categories cc ON cc.content_id=s.champion_content_id AND cc.category_id=s.category_id WHERE cc.status<>'approved';
  UPDATE public.vote_slots s SET champion_content_id=NULL,version=version+1,updated_at=now() FROM public.content_categories cc WHERE cc.content_id=s.champion_content_id AND cc.category_id=s.category_id AND cc.status<>'approved';
  INSERT INTO private.model_migrations(name) VALUES('creator-single-category-v1');
 END IF;
END $migration$;
CREATE UNIQUE INDEX IF NOT EXISTS content_single_category_idx ON public.content_categories(content_id) WHERE status IN ('approved','pending');
REVOKE ALL ON ALL FUNCTIONS IN SCHEMA api FROM PUBLIC;

